import{_ as e,o as i,c as s,an as a}from"./chunks/framework.BZkRsxf_.js";const g=JSON.parse('{"title":"Inspecting input and output","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started/inspecting_output.md","filePath":"getting_started/inspecting_output.md","lastUpdated":null}'),n={name:"getting_started/inspecting_output.md"};function r(l,t,h,d,o,p){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="Inspecting-output" tabindex="-1">Inspecting input and output <a class="header-anchor" href="#Inspecting-output" aria-label="Permalink to &quot;Inspecting input and output {#Inspecting-output}&quot;">​</a></h1><p>AtmosTransport reads a <strong>transport binary</strong> and writes <strong>NetCDF snapshots</strong>. The two formats have different jobs:</p><table tabindex="0"><thead><tr><th style="text-align:right;">File</th><th style="text-align:right;">Contains</th><th style="text-align:right;">Typical question</th></tr></thead><tbody><tr><td style="text-align:right;"><code>*.bin</code></td><td style="text-align:right;">grid, air mass, mass fluxes, and optional physics fields</td><td style="text-align:right;">Can this forcing run the operators I requested?</td></tr><tr><td style="text-align:right;"><code>*.nc</code></td><td style="text-align:right;">tracer and air-mass snapshots</td><td style="text-align:right;">What did the simulated atmosphere look like?</td></tr></tbody></table><p>The <a href="/AtmosTransport.jl/dev/getting_started/quickstart#Quickstart">Quickstart</a> creates both kinds beneath <code>data/quickstart/</code>.</p><h2 id="Check-a-transport-binary-before-running" tabindex="-1">Check a transport binary before running <a class="header-anchor" href="#Check-a-transport-binary-before-running" aria-label="Permalink to &quot;Check a transport binary before running {#Check-a-transport-binary-before-running}&quot;">​</a></h2><p>Use the inspector on any binary, synthetic or preprocessed:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/diagnostics/inspect_transport_binary.jl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    data/quickstart/synthetic_latlon_v4.bin</span></span></code></pre></div><p>It reports the grid, precision, mass basis, time windows, payload fields, and operator capabilities. For example, the synthetic quickstart has advection and replay fields but no convection or diffusion fields. Asking the runtime to use an unsupported operator therefore fails immediately with a useful error.</p><p>All current inputs must have <code>format_version = 4</code>. Regenerate an older binary with the current preprocessor; the runtime does not guess old semantics.</p><p>From Julia, the same check is:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AtmosTransport</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">capabilities </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> inspect_binary</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/quickstart/synthetic_latlon_v4.bin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capabilities</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grid_type capabilities</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mass_basis</span></span></code></pre></div><h2 id="Open-the-quickstart-output-in-Julia" tabindex="-1">Open the quickstart output in Julia <a class="header-anchor" href="#Open-the-quickstart-output-in-Julia" aria-label="Permalink to &quot;Open the quickstart output in Julia {#Open-the-quickstart-output-in-Julia}&quot;">​</a></h2><p><code>NCDatasets</code> is already a project dependency:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NCDatasets</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NCDataset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data/quickstart/synthetic_output.nc&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ds</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keys</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ds</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">variables))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    co2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ds[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;co2_bl_column_mean&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">][:, :, :]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;shape: &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(co2))</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;range: &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">extrema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(co2))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">end</span></span></code></pre></div><p>For the maintained example, the column-mean array has shape <code>(36, 18, 5)</code>: longitude × latitude × output time. Its values begin at <code>4e-4</code> and develop a longitudinal pattern as the synthetic flow transports the tracer.</p><p>If you have NetCDF command-line tools installed, this gives a quick structural check without starting Julia:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ncdump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -h</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/quickstart/synthetic_output.nc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> less</span></span></code></pre></div><h2 id="Understand-variable-names-and-dimensions" tabindex="-1">Understand variable names and dimensions <a class="header-anchor" href="#Understand-variable-names-and-dimensions" aria-label="Permalink to &quot;Understand variable names and dimensions {#Understand-variable-names-and-dimensions}&quot;">​</a></h2><p>Tracer names come from the TOML table name. For <code>[tracers.co2_bl]</code>, output variables begin with <code>co2_bl</code>:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Variable</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>co2_bl</code></td><td style="text-align:right;">tracer mixing ratio on every model level</td></tr><tr><td style="text-align:right;"><code>co2_bl_column_mean</code></td><td style="text-align:right;">air-mass-weighted column mean</td></tr><tr><td style="text-align:right;"><code>co2_bl_column_mass_per_area</code></td><td style="text-align:right;">tracer column mass per unit area</td></tr><tr><td style="text-align:right;"><code>air_mass</code></td><td style="text-align:right;">air mass on every model level</td></tr><tr><td style="text-align:right;"><code>column_air_mass_per_area</code></td><td style="text-align:right;">vertically integrated air mass per unit area</td></tr></tbody></table><p>The horizontal dimensions depend on the grid:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Grid</th><th style="text-align:right;">Full three-dimensional tracer</th><th style="text-align:right;">Column mean</th></tr></thead><tbody><tr><td style="text-align:right;">Latitude–longitude</td><td style="text-align:right;"><code>(lon, lat, lev, time)</code></td><td style="text-align:right;"><code>(lon, lat, time)</code></td></tr><tr><td style="text-align:right;">Reduced Gaussian</td><td style="text-align:right;">native cells plus rasterized products</td><td style="text-align:right;">native and <code>(lon, lat, time)</code> products</td></tr><tr><td style="text-align:right;">Cubed sphere</td><td style="text-align:right;"><code>(Xdim, Ydim, face, lev, time)</code></td><td style="text-align:right;"><code>(Xdim, Ydim, face, time)</code></td></tr></tbody></table><p>Some Python tools display dimensions in the opposite order because they follow row-major conventions. Read the variable&#39;s named dimensions instead of assuming an axis order.</p><p>The <code>[output.fields]</code> table can intentionally omit full three-dimensional fields, select tracers, or select model levels. Check that table first when an expected variable is absent. See <a href="/AtmosTransport.jl/dev/config/output_schema#Output-schema">Output schema</a> for every option.</p><h2 id="Interpret-the-run-summary" tabindex="-1">Interpret the run summary <a class="header-anchor" href="#Interpret-the-run-summary" aria-label="Permalink to &quot;Interpret the run summary {#Interpret-the-run-summary}&quot;">​</a></h2><p>At shutdown the runner prints relative air-mass and conservative tracer-storage changes. The synthetic quickstart is closed and has no sources, so both should be near the floating-point noise floor. A source-driven experiment can legitimately change model storage; compare the change with the reported integrated source rather than expecting zero. This storage is <code>mixing ratio × carrier-air-mass</code>, not physical kilograms of the tracer species.</p><h2 id="Common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#Common-problems" aria-label="Permalink to &quot;Common problems {#Common-problems}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Symptom</th><th style="text-align:right;">First check</th></tr></thead><tbody><tr><td style="text-align:right;">Binary rejected before the run</td><td style="text-align:right;">Confirm <code>format_version = 4</code> and inspect its capabilities.</td></tr><tr><td style="text-align:right;">Requested convection or diffusion is unavailable</td><td style="text-align:right;">Reprocess forcing with the required fields enabled.</td></tr><tr><td style="text-align:right;">A tracer variable is missing</td><td style="text-align:right;">Check <code>[output.fields]</code> and the tracer table name.</td></tr><tr><td style="text-align:right;">Extreme CFL values or non-finite output</td><td style="text-align:right;">Check vertical ordering, flux time units, and whether the binary was produced by the current preprocessor.</td></tr><tr><td style="text-align:right;">A closed run has appreciable mass drift</td><td style="text-align:right;">Check the conservation budget and replay gate before interpreting tracer results.</td></tr></tbody></table><p>Continue with <a href="/AtmosTransport.jl/dev/concepts/architecture#Architecture-tour">Architecture tour</a> for the model&#39;s moving pieces, or <a href="/AtmosTransport.jl/dev/getting_started/first_run#Run-with-real-meteorology">Run with real meteorology</a> to replace the synthetic forcing.</p>`,29)])])}const u=e(n,[["render",r]]);export{g as __pageData,u as default};
